{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "network_loss",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' src, count(*) n_over_100s, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST' AND attr_span_kind='Client' AND duration > 100000000000 UNION ALL SELECT 'norm', count(*), sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END), max(duration)/1e6 FROM normal_traces WHERE service_name='ts-preserve-service' AND span_name='POST' AND attr_span_kind='Client' AND duration > 100000000000", "claim": "16 preserve-to-downstream POST calls exceed 100 s in abnormal (14 errors), none in normal."},
        {"kind": "log", "sql": "SELECT time, level, message, attr_k8s_pod_name FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' ORDER BY time LIMIT 2", "claim": "Preserve logs SEVERE: I/O error on POST to ts-basic-service /basic/travel, connection timed out."},
        {"kind": "trace", "sql": "WITH pc AS (SELECT span_id, trace_id, duration, attr_status_code FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST' AND attr_span_kind='Client') SELECT s.service_name, s.span_name, s.attr_span_kind, count(*) n, approx_quantile(pc.duration,0.5)/1e6 client_p50_ms, max(pc.duration)/1e6 client_max_ms, approx_quantile(s.duration,0.5)/1e6 srv_p50_ms, max(s.duration)/1e6 srv_max_ms FROM pc JOIN abnormal_traces s ON s.parent_span_id=pc.span_id AND s.trace_id=pc.trace_id GROUP BY 1,2,3 ORDER BY client_max_ms DESC", "claim": "Preserve-to-basic calls wait about 240 s while basic's server span takes only about 25 ms."},
        {"kind": "metric", "sql": "SELECT 'abn' src, metric, attr_source, attr_destination, count(*) n, sum(value) total FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%preserve-service%' AND attr_destination LIKE '%basic%' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', metric, attr_source, attr_destination, count(*), sum(value) FROM normal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%preserve-service%' AND attr_destination LIKE '%basic%' GROUP BY 1,2,3,4", "claim": "TCP flag packets on the preserve-to-basic connection rise from about 2145 to 3611 in abnormal."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-preserve-service",
      "evidence": [
        {"kind": "trace", "sql": "WITH pc AS (SELECT span_id, trace_id FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='PreserveController.preserve') SELECT c.service_name, c.span_name, c.attr_span_kind, count(*) n, max(c.duration)/1e6 max_ms, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces c JOIN pc ON c.parent_span_id=pc.span_id AND c.trace_id=pc.trace_id GROUP BY 1,2,3 ORDER BY max_ms DESC", "claim": "Preserve's PreserveController.preserve spans wait on its outgoing POST calls, which reach basic with timeouts."}
      ]
    },
