        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind k, count(*) n, approx_quantile(duration,0.5)/1e6 p50, approx_quantile(duration,0.95)/1e6 p95, avg(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY 1,2", "claim": "ui-dashboard's preserve endpoint shows p95 about 234 s and 64% error share in abnormal."}
